<h1>Estoque</h1>
<form method="post" action="<?= e(url('/admin/estoque')) ?>" class="card form-stack" data-once>
<?= csrf_field() ?><h2>Registrar movimentação</h2>
<div class="field"><label for="book_id">Livro</label><select id="book_id" name="book_id" required><option value="">Escolha</option><?php foreach ($books as $book): ?><option value="<?= (int) $book['id'] ?>"<?= $bookId === (int) $book['id'] ? ' selected' : '' ?>><?= e($book['title']) ?> · <?= (int) $book['stock'] ?> em estoque</option><?php endforeach; ?></select></div>
<div class="form-grid"><div class="field"><label for="type">Movimentação</label><select id="type" name="type"><option value="entrada">Entrada: somar unidades</option><option value="saida">Saída: retirar unidades</option><option value="ajuste">Ajuste: informar o estoque final</option></select></div><div class="field"><label for="quantity">Quantidade (no ajuste, estoque final)</label><input id="quantity" name="quantity" type="number" min="0" max="100000" step="1" required></div></div>
<div class="field"><label for="note">Motivo</label><input id="note" name="note" maxlength="255" required></div><button class="btn">Registrar</button></form>
<section class="section"><h2>Histórico</h2><form method="get" class="search-form"><label for="q">Buscar por livro</label><div class="search-row"><input type="search" id="q" name="q" value="<?= e($q) ?>"><button class="btn">Buscar</button></div></form>
<?php if (!$rows): ?><p>Nenhuma movimentação encontrada.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data</th><th>Livro</th><th>Tipo</th><th>Variação</th><th>Estoque final</th><th>Responsável / motivo</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td data-label="Data"><?= e(format_date($row['created_at'])) ?></td><td data-label="Livro"><?= e($row['title']) ?></td><td data-label="Tipo"><?= e(ucfirst($row['type'])) ?></td><td data-label="Variação"><?= (int) $row['quantity'] > 0 ? '+' : '' ?><?= (int) $row['quantity'] ?></td><td data-label="Estoque final"><?= (int) $row['stock_after'] ?></td><td data-label="Responsável / motivo"><?= e($row['actor'] ?? 'Sistema') ?><br><?= e($row['note']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?= render_template('admin/_pagination', compact('page','pages','total') + ['path' => '/admin/estoque', 'filters' => ['q' => $q, 'livro' => $bookId]]) ?></section>
